import { register } from './i18n.js';

const REPO = 'https://github.com/yakuzaax/anonyx';

register({
  'h.meta': ['How Anonyx finds, follows and hides faces, step by step, entirely inside your browser.', 'Comment Anonyx trouve, suit et masque les visages, étape par étape, entièrement dans votre navigateur.', 'Cómo Anonyx encuentra, sigue y oculta rostros, paso a paso, por completo dentro de tu navegador.', 'كيف يجد Anonyx الوجوه ويتتبّعها ويخفيها، خطوة بخطوة، بالكامل داخل متصفحك.', 'Anonyx yüzleri nasıl bulur, takip eder ve gizler; adım adım, tamamen tarayıcınızın içinde.'],
  'h.pagetitle': ['Anonyx · how it works', 'Anonyx · comment ça marche', 'Anonyx · cómo funciona', 'Anonyx · كيف يعمل', 'Anonyx · nasıl çalışır'],
  'h.title': ['How<br>it<br>works.', 'Comment<br>ça<br>marche.', 'Cómo<br>funciona.', 'كيف<br>يعمل.', 'Nasıl<br>çalışır.'],
  'h.lead': ['Everything happens in your browser. Here is each step, from the file you pick to the file you save, with the real numbers used by the code.', 'Tout se passe dans votre navigateur. Voici chaque étape, du fichier choisi au fichier enregistré, avec les vrais chiffres utilisés par le code.', 'Todo ocurre en tu navegador. Aquí está cada paso, desde el archivo que eliges hasta el que guardas, con las cifras reales que usa el código.', 'كل شيء يحدث في متصفحك. هذه كل الخطوات، من الملف الذي تختاره إلى الملف الذي تحفظه، مع الأرقام الفعلية التي تستخدمها الشيفرة.', 'Her şey tarayıcınızda olur. Seçtiğiniz dosyadan kaydettiğiniz dosyaya kadar her adım, kodun kullandığı gerçek sayılarla burada.'],

  'h.f1b': ['Open', 'Ouvrir', 'Abrir', 'الفتح', 'Aç'],
  'h.f1s': ['your file stays on the device', 'votre fichier reste sur l’appareil', 'tu archivo se queda en el dispositivo', 'ملفك يبقى على الجهاز', 'dosyanız cihazda kalır'],
  'h.f2b': ['Read', 'Lire', 'Leer', 'القراءة', 'Oku'],
  'h.f2s': ['30 images per second', '30 images par seconde', '30 imágenes por segundo', '30 صورة في الثانية', 'saniyede 30 görüntü'],
  'h.f3b': ['Detect', 'Détecter', 'Detectar', 'الكشف', 'Algıla'],
  'h.f3s': ['a face model, in the background', 'un modèle de visages, en arrière-plan', 'un modelo de rostros, en segundo plano', 'نموذج للوجوه، في الخلفية', 'bir yüz modeli, arka planda'],
  'h.f4b': ['Follow', 'Suivre', 'Seguir', 'التتبّع', 'Takip et'],
  'h.f4s': ['link detections over time', 'relier les détections dans le temps', 'enlazar las detecciones en el tiempo', 'ربط عمليات الكشف عبر الزمن', 'algılamaları zamanla bağla'],
  'h.f5b': ['Review', 'Vérifier', 'Revisar', 'المراجعة', 'Gözden geçir'],
  'h.f5s': ['you fix what is wrong', 'vous corrigez ce qui ne va pas', 'corriges lo que falle', 'تصحّح ما هو خاطئ', 'yanlışları siz düzeltirsiniz'],
  'h.f6b': ['Export', 'Exporter', 'Exportar', 'التصدير', 'Dışa aktar'],
  'h.f6s': ['a new file, masks painted in', 'un nouveau fichier, masques peints dedans', 'un archivo nuevo, con las máscaras pintadas', 'ملف جديد تُرسَم فيه الأقنعة', 'yeni bir dosya, maskeler içine çizilmiş'],

  'h.s1': ['1 · Loading the tool', '1 · Chargement de l’outil', '1 · Carga de la herramienta', '1 · تحميل الأداة', '1 · Aracın yüklenmesi'],
  'h.s1p1': ['The page, the fonts, the face-detection model (YuNet, 338 KB) and its engine (ONNX Runtime, compiled to WebAssembly) all come from this one address. A security rule in the page, the Content-Security-Policy, forbids the browser from contacting any other address, so even a bug could not send anything out.', 'La page, les polices, le modèle de détection de visages (YuNet, 338 Ko) et son moteur (ONNX Runtime, compilé en WebAssembly) viennent tous de cette seule adresse. Une règle de sécurité de la page, la Content-Security-Policy, interdit au navigateur de contacter toute autre adresse : même un bogue ne pourrait rien envoyer.', 'La página, las fuentes, el modelo de detección de rostros (YuNet, 338 KB) y su motor (ONNX Runtime, compilado a WebAssembly) vienen todos de esta única dirección. Una regla de seguridad de la página, la Content-Security-Policy, impide que el navegador contacte con cualquier otra dirección, así que ni un error podría enviar nada.', 'الصفحة والخطوط ونموذج كشف الوجوه (YuNet، 338 ك.ب) ومحرّكه (ONNX Runtime المُصرَّف إلى WebAssembly) كلها تأتي من هذا العنوان الواحد. قاعدة أمان في الصفحة، هي Content-Security-Policy، تمنع المتصفح من الاتصال بأي عنوان آخر، فحتى الخلل البرمجي لا يستطيع إرسال شيء.', 'Sayfa, yazı tipleri, yüz algılama modeli (YuNet, 338 KB) ve motoru (WebAssembly’ye derlenmiş ONNX Runtime) hep bu tek adresten gelir. Sayfadaki bir güvenlik kuralı olan Content-Security-Policy, tarayıcının başka hiçbir adrese bağlanmasını yasaklar; bir hata bile hiçbir şey gönderemez.'],
  'h.s1p2': ['The model runs in background workers: up to 3 (2 on iPhone, 4 on a computer with 8 cores and 8 GB), always leaving one processor core free so the page stays smooth. If workers are not available, it runs on the page itself, more slowly. If the optional WebGPU build of the engine is installed and the device supports it, the graphics chip does the work; if anything fails, WebAssembly takes over.', 'Le modèle tourne dans des processus d’arrière-plan (workers) : jusqu’à 3 (2 sur iPhone, 4 sur un ordinateur de 8 cœurs et 8 Go), en laissant toujours un cœur libre pour que la page reste fluide. Sans workers, il tourne dans la page, plus lentement. Si la version WebGPU facultative du moteur est installée et que l’appareil la gère, c’est la puce graphique qui travaille ; en cas d’échec, WebAssembly prend le relais.', 'El modelo se ejecuta en procesos en segundo plano (workers): hasta 3 (2 en iPhone, 4 en un ordenador de 8 núcleos y 8 GB), dejando siempre un núcleo libre para que la página vaya fluida. Si no hay workers, se ejecuta en la propia página, más despacio. Si la versión WebGPU opcional del motor está instalada y el dispositivo la admite, trabaja el chip gráfico; si algo falla, toma el relevo WebAssembly.', 'يعمل النموذج في عمليات خلفية (workers): حتى 3 (اثنتان على الآيفون، وأربع على حاسوب بثمانية أنوية و8 غ.ب)، مع ترك نواة معالج حرة دائمًا لتبقى الصفحة سلسة. إن لم تتوفر العمليات الخلفية يعمل في الصفحة نفسها بشكل أبطأ. وإذا ثُبِّتت نسخة WebGPU الاختيارية من المحرّك وكان الجهاز يدعمها فإن شريحة الرسوميات تقوم بالعمل، وعند أي فشل يتولى WebAssembly المهمة.', 'Model arka plan işçilerinde (worker) çalışır: en fazla 3 (iPhone’da 2, 8 çekirdekli ve 8 GB’lık bilgisayarda 4); sayfa akıcı kalsın diye her zaman bir işlemci çekirdeği boş bırakılır. Worker yoksa sayfanın kendisinde, daha yavaş çalışır. Motorun isteğe bağlı WebGPU sürümü kuruluysa ve cihaz destekliyorsa işi grafik yongası yapar; bir şey ters giderse WebAssembly devralır.'],

  'h.s2': ['2 · Reading your file', '2 · Lecture de votre fichier', '2 · Lectura de tu archivo', '2 · قراءة ملفك', '2 · Dosyanızın okunması'],
  'h.s2p1': ['Your file is never uploaded. The browser opens it through a private local address (<code>blob:</code>) that exists only in this tab. HEIC photos are read only if the browser can decode them itself (Safari and iPhone can).', 'Votre fichier n’est jamais envoyé. Le navigateur l’ouvre par une adresse locale privée (<code>blob:</code>) qui n’existe que dans cet onglet. Les photos HEIC ne sont lues que si le navigateur sait les décoder lui-même (Safari et l’iPhone le savent).', 'Tu archivo nunca se sube. El navegador lo abre mediante una dirección local privada (<code>blob:</code>) que solo existe en esta pestaña. Las fotos HEIC solo se leen si el navegador sabe decodificarlas por sí mismo (Safari y el iPhone sí).', 'لا يُرفَع ملفك أبدًا. يفتحه المتصفح عبر عنوان محلي خاص (<code>blob:</code>) لا وجود له إلا في هذا اللسان. لا تُقرأ صور HEIC إلا إذا كان المتصفح قادرًا على فك ترميزها بنفسه (Safari والآيفون يستطيعان).', 'Dosyanız asla yüklenmez. Tarayıcı onu yalnızca bu sekmede var olan özel bir yerel adres (<code>blob:</code>) üzerinden açar. HEIC fotoğraflar yalnızca tarayıcı kendisi çözebiliyorsa okunur (Safari ve iPhone çözebilir).'],
  'h.s2p2': ['Videos are scaled so the longest side is at most 1920 px, photos 4096 px. A video is analysed at 30 images per second. To do it quickly, Anonyx plays the video and copies each image as it appears. If the phone skips images, playback slows down automatically. If playback is not possible, it jumps to each image one by one, which is slower but sure.', 'Les vidéos sont réduites pour que le grand côté fasse au plus 1920 px, les photos 4096 px. Une vidéo est analysée à 30 images par seconde. Pour aller vite, Anonyx lit la vidéo et copie chaque image à son affichage. Si le téléphone saute des images, la lecture ralentit automatiquement. Si la lecture est impossible, il saute à chaque image une par une, plus lent mais sûr.', 'Los vídeos se reducen para que el lado más largo mida como máximo 1920 px, las fotos 4096 px. Un vídeo se analiza a 30 imágenes por segundo. Para hacerlo rápido, Anonyx reproduce el vídeo y copia cada imagen cuando aparece. Si el teléfono se salta imágenes, la reproducción se ralentiza sola. Si no se puede reproducir, salta a cada imagen una por una, más lento pero seguro.', 'تُصغَّر مقاطع الفيديو بحيث لا يتجاوز أطول ضلع 1920 بكسل، والصور 4096 بكسل. يُحلَّل الفيديو بمعدل 30 صورة في الثانية. وللسرعة يشغّل Anonyx الفيديو وينسخ كل صورة عند ظهورها. إذا تخطّى الهاتف بعض الصور تبطئ سرعة التشغيل تلقائيًا. وإن تعذّر التشغيل ينتقل إلى كل صورة على حدة، وهذا أبطأ لكنه مضمون.', 'Videolar en uzun kenar en fazla 1920 px, fotoğraflar 4096 px olacak şekilde küçültülür. Video saniyede 30 görüntü ile analiz edilir. Hızlı olması için Anonyx videoyu oynatır ve her görüntüyü göründüğü anda kopyalar. Telefon görüntü atlarsa oynatma otomatik yavaşlar. Oynatma mümkün değilse her görüntüye tek tek atlar; daha yavaş ama güvenilirdir.'],

  'h.s3': ['3 · Finding faces', '3 · Recherche des visages', '3 · Búsqueda de rostros', '3 · إيجاد الوجوه', '3 · Yüzlerin bulunması'],
  'h.s3p': ['Each image is given to YuNet, a small face-detection network. The image is padded to a multiple of 32 px, then the network looks at it at three scales (steps of 8, 16 and 32 px) and proposes boxes, each with a score between 0 and 1. Overlapping boxes on the same face are merged (overlap above 30%).', 'Chaque image est confiée à YuNet, un petit réseau de détection de visages. L’image est complétée jusqu’à un multiple de 32 px, puis le réseau la regarde à trois échelles (pas de 8, 16 et 32 px) et propose des boîtes, chacune avec un score entre 0 et 1. Les boîtes qui se chevauchent sur un même visage sont fusionnées (recouvrement supérieur à 30 %).', 'Cada imagen se entrega a YuNet, una pequeña red de detección de rostros. La imagen se rellena hasta un múltiplo de 32 px y la red la examina a tres escalas (pasos de 8, 16 y 32 px) y propone cajas, cada una con una puntuación entre 0 y 1. Las cajas que se solapan sobre un mismo rostro se fusionan (solape superior al 30 %).', 'تُمرَّر كل صورة إلى YuNet، وهي شبكة صغيرة لكشف الوجوه. تُملأ الصورة حتى تصبح أبعادها من مضاعفات 32 بكسل، ثم تفحصها الشبكة بثلاثة مقاييس (خطوات 8 و16 و32 بكسل) وتقترح مربعات لكل منها درجة بين 0 و1. تُدمج المربعات المتداخلة على الوجه نفسه (تداخل يفوق 30٪).', 'Her görüntü, küçük bir yüz algılama ağı olan YuNet’e verilir. Görüntü 32 px’in katına tamamlanır, ağ onu üç ölçekte (8, 16 ve 32 px adımlarla) inceler ve her biri 0 ile 1 arasında puan taşıyan kutular önerir. Aynı yüz üzerindeki çakışan kutular birleştirilir (çakışma %30’un üzerinde).'],
  'h.s3f1': ['<b>Dark scenes.</b> If an image is very dark (average brightness under 40 out of 255), it is analysed twice: as is, and brightened with a square-root curve. The model was also retrained on night photos.', '<b>Scènes sombres.</b> Si une image est très sombre (luminosité moyenne sous 40 sur 255), elle est analysée deux fois : telle quelle, et éclaircie par une courbe en racine carrée. Le modèle a aussi été réentraîné sur des photos de nuit.', '<b>Escenas oscuras.</b> Si una imagen es muy oscura (brillo medio por debajo de 40 sobre 255), se analiza dos veces: tal cual y aclarada con una curva de raíz cuadrada. El modelo también se reentrenó con fotos nocturnas.', '<b>المشاهد المظلمة.</b> إذا كانت الصورة شديدة الظلمة (متوسط السطوع أقل من 40 من 255) تُحلَّل مرتين: كما هي، ومُفتَّحة بمنحنى الجذر التربيعي. وقد أُعيد تدريب النموذج أيضًا على صور ليلية.', '<b>Karanlık sahneler.</b> Bir görüntü çok karanlıksa (ortalama parlaklık 255 üzerinden 40’ın altında) iki kez analiz edilir: olduğu gibi ve karekök eğrisiyle aydınlatılmış hâliyle. Model ayrıca gece fotoğraflarıyla yeniden eğitilmiştir.'],
  'h.s3f2': ['<b>A second look.</b> Every third image, and whenever a box is doubtful, the image is analysed again at one third of the size. Large faces close to the camera are sometimes recognised better when smaller.', '<b>Un second regard.</b> Une image sur trois, et chaque fois qu’une boîte est douteuse, l’image est analysée de nouveau au tiers de sa taille. Les grands visages proches de la caméra sont parfois mieux reconnus en plus petit.', '<b>Una segunda mirada.</b> Cada tres imágenes, y siempre que una caja es dudosa, la imagen se analiza de nuevo a un tercio del tamaño. Los rostros grandes y cercanos a la cámara a veces se reconocen mejor más pequeños.', '<b>نظرة ثانية.</b> كل صورة ثالثة، وكلما كان مربع مشكوكًا فيه، تُحلَّل الصورة مرة أخرى بثلث حجمها. الوجوه الكبيرة القريبة من الكاميرا يُتعرَّف عليها أحيانًا بشكل أفضل حين تصغر.', '<b>İkinci bakış.</b> Her üçüncü görüntüde ve bir kutu şüpheli olduğunda görüntü, boyutunun üçte birinde yeniden analiz edilir. Kameraya yakın büyük yüzler küçülünce bazen daha iyi tanınır.'],
  'h.s3f3': ['<b>Fast mode.</b> Analyses at 1280 px instead of 1920 px and skips the head pass. Quicker on a slow phone, but it may miss very small faces.', '<b>Mode rapide.</b> Analyse à 1280 px au lieu de 1920 px et saute la passe « têtes ». Plus rapide sur un téléphone lent, mais peut rater de très petits visages.', '<b>Modo rápido.</b> Analiza a 1280 px en lugar de 1920 px y omite la pasada de cabezas. Más rápido en un teléfono lento, pero puede omitir rostros muy pequeños.', '<b>الوضع السريع.</b> يحلّل بدقة 1280 بكسل بدل 1920 ويتخطى مرحلة الرؤوس. أسرع على هاتف بطيء لكنه قد تفوته وجوه صغيرة جدًا.', '<b>Hızlı mod.</b> 1920 px yerine 1280 px’te analiz eder ve baş geçişini atlar. Yavaş bir telefonda daha hızlıdır ama çok küçük yüzleri kaçırabilir.'],
  'h.s3f4': ['<b>Heads, from any side (optional model).</b> When a head model (<code>models/head.onnx</code>) is installed, a second pass looks for heads every third image and on photos: profiles, backs of heads, helmets, masks. A head box is added only if no face was found inside it. Without that file, this pass does nothing.', '<b>Têtes, de n’importe quel côté (modèle facultatif).</b> Quand un modèle de têtes (<code>models/head.onnx</code>) est installé, une seconde passe cherche les têtes une image sur trois et sur les photos : profils, nuques, casques, masques. Une boîte de tête n’est ajoutée que si aucun visage n’a été trouvé dedans. Sans ce fichier, cette passe ne fait rien.', '<b>Cabezas, desde cualquier lado (modelo opcional).</b> Cuando hay un modelo de cabezas (<code>models/head.onnx</code>) instalado, una segunda pasada busca cabezas cada tres imágenes y en las fotos: perfiles, nucas, cascos, mascarillas. Solo se añade una caja de cabeza si no se encontró ningún rostro dentro. Sin ese archivo, esta pasada no hace nada.', '<b>الرؤوس من أي جهة (نموذج اختياري).</b> عند تثبيت نموذج للرؤوس (<code>models/head.onnx</code>) تبحث مرحلة ثانية عن الرؤوس كل صورة ثالثة وفي الصور الثابتة: الوجوه الجانبية ومؤخرة الرأس والخوذات والكمامات. لا يُضاف مربع رأس إلا إذا لم يُعثر على وجه بداخله. وبدون هذا الملف لا تفعل هذه المرحلة شيئًا.', '<b>Her yönden baş (isteğe bağlı model).</b> Bir baş modeli (<code>models/head.onnx</code>) kuruluysa ikinci bir geçiş her üçüncü görüntüde ve fotoğraflarda başları arar: profil, ensesi, kask, maske. Bir baş kutusu yalnızca içinde yüz bulunmadıysa eklenir. Bu dosya yoksa bu geçiş hiçbir şey yapmaz.'],

  'h.s4': ['4 · Deciding what is a face', '4 · Décider ce qui est un visage', '4 · Decidir qué es un rostro', '4 · تحديد ما هو وجه', '4 · Neyin yüz olduğuna karar verme'],
  'h.s4p1': ['A box is kept only if its score is high enough, and the bar depends on its size. Small faces are hard to see, and an extra mask costs little, so the bar is low. Large boxes with a medium score are usually false alarms (a wall, a tree), so the bar is high.', 'Une boîte n’est gardée que si son score est assez haut, et le seuil dépend de sa taille. Les petits visages sont difficiles à voir et un masque en trop coûte peu : le seuil est bas. Les grandes boîtes à score moyen sont souvent de fausses alertes (un mur, un arbre) : le seuil est haut.', 'Una caja solo se conserva si su puntuación es suficientemente alta, y el umbral depende de su tamaño. Los rostros pequeños son difíciles de ver y una máscara de más cuesta poco, así que el umbral es bajo. Las cajas grandes con puntuación media suelen ser falsas alarmas (una pared, un árbol), así que el umbral es alto.', 'لا يُحتفَظ بالمربع إلا إذا كانت درجته عالية بما يكفي، ويعتمد الحد على حجمه. الوجوه الصغيرة يصعب رؤيتها وقناع زائد كلفته قليلة، فيكون الحد منخفضًا. أما المربعات الكبيرة ذات الدرجة المتوسطة فغالبًا إنذارات كاذبة (جدار، شجرة)، فيكون الحد مرتفعًا.', 'Bir kutu yalnızca puanı yeterince yüksekse tutulur ve eşik boyutuna bağlıdır. Küçük yüzler zor görülür ve fazladan bir maskenin maliyeti azdır; eşik düşüktür. Orta puanlı büyük kutular çoğunlukla yanlış alarmdır (duvar, ağaç); eşik yüksektir.'],
  'h.c1aria': ['Minimum score needed, by face size', 'Score minimal requis, selon la taille du visage', 'Puntuación mínima necesaria, según el tamaño del rostro', 'الدرجة الدنيا المطلوبة بحسب حجم الوجه', 'Yüz boyutuna göre gereken en düşük puan'],
  'h.c1x': ['face width / shorter side of the image', 'largeur du visage / petit côté de l’image', 'ancho del rostro / lado corto de la imagen', 'عرض الوجه / الضلع الأقصر للصورة', 'yüz genişliği / görüntünün kısa kenarı'],
  'h.c1y': ['minimum score', 'score minimal', 'puntuación mínima', 'الدرجة الدنيا', 'en düşük puan'],
  'h.s4p2': ['Under 12% of the shorter side, 0.20 is enough. Between 12% and 25%, the bar rises from 0.30 to 0.85. Above 25%, it stays at 0.85. One exception: a box from 0.30 is accepted if the second look at one third of the size finds the same face.', 'Sous 12 % du petit côté, 0,20 suffit. Entre 12 % et 25 %, le seuil monte de 0,30 à 0,85. Au-dessus de 25 %, il reste à 0,85. Une exception : une boîte dès 0,30 est acceptée si le second regard au tiers de la taille retrouve le même visage.', 'Por debajo del 12 % del lado corto basta con 0,20. Entre el 12 % y el 25 %, el umbral sube de 0,30 a 0,85. Por encima del 25 % se queda en 0,85. Una excepción: se acepta una caja desde 0,30 si la segunda mirada a un tercio del tamaño encuentra el mismo rostro.', 'تحت 12٪ من الضلع الأقصر يكفي 0.20. بين 12٪ و25٪ يرتفع الحد من 0.30 إلى 0.85. وفوق 25٪ يبقى 0.85. استثناء واحد: يُقبل مربع من 0.30 إذا وجدت النظرة الثانية بثلث الحجم الوجه نفسه.', 'Kısa kenarın %12’sinin altında 0,20 yeterlidir. %12 ile %25 arasında eşik 0,30’dan 0,85’e çıkar. %25’in üzerinde 0,85’te kalır. Bir istisna: üçte bir boyuttaki ikinci bakış aynı yüzü bulursa 0,30’dan itibaren bir kutu kabul edilir.'],

  'h.s5': ['5 · Following faces over time', '5 · Suivre les visages dans le temps', '5 · Seguir los rostros en el tiempo', '5 · تتبّع الوجوه عبر الزمن', '5 · Yüzleri zamanla takip etme'],
  'h.s5p': ['Detections are linked from one image to the next. A new box continues an existing face if it is close (within about 1.6 times the average size of the two boxes) and of similar size (less than 2.5 times bigger or smaller). A face may disappear for up to 20 images (0.67 s) and still be the same one.', 'Les détections sont reliées d’une image à la suivante. Une nouvelle boîte prolonge un visage existant si elle est proche (à environ 1,6 fois la taille moyenne des deux boîtes) et de taille voisine (moins de 2,5 fois plus grande ou plus petite). Un visage peut disparaître jusqu’à 20 images (0,67 s) et rester le même.', 'Las detecciones se enlazan de una imagen a la siguiente. Una caja nueva continúa un rostro existente si está cerca (a unas 1,6 veces el tamaño medio de las dos cajas) y es de tamaño parecido (menos de 2,5 veces mayor o menor). Un rostro puede desaparecer hasta 20 imágenes (0,67 s) y seguir siendo el mismo.', 'تُربط عمليات الكشف من صورة إلى التالية. يمدّد المربع الجديد وجهًا موجودًا إذا كان قريبًا (ضمن نحو 1.6 ضعف متوسط حجم المربعين) ومتقارب الحجم (أقل من 2.5 ضعف بالزيادة أو النقصان). ويمكن أن يختفي الوجه حتى 20 صورة (0.67 ثانية) ويبقى هو نفسه.', 'Algılamalar bir görüntüden sonrakine bağlanır. Yeni bir kutu, yakınsa (iki kutunun ortalama boyutunun yaklaşık 1,6 katı içinde) ve benzer boyuttaysa (2,5 kattan az büyük veya küçük) mevcut bir yüzü sürdürür. Bir yüz 20 görüntüye (0,67 sn) kadar kaybolup yine aynı yüz sayılabilir.'],
  'h.c2aria': ['Detections, gap filled by interpolation, and extra margin at both ends', 'Détections, trou comblé par interpolation et marge ajoutée aux deux bouts', 'Detecciones, hueco rellenado por interpolación y margen extra en ambos extremos', 'عمليات كشف وفجوة مملوءة بالاستيفاء وهامش إضافي في الطرفين', 'Algılamalar, enterpolasyonla doldurulan boşluk ve iki uçta ek pay'],
  'h.c2det': ['detected', 'détecté', 'detectado', 'مكتشف', 'algılandı'],
  'h.c2fill': ['filled', 'comblé', 'relleno', 'مملوء', 'dolduruldu'],
  'h.s5f1': ['<b>Gaps are filled.</b> Between two detections, the box is interpolated, so a face missed for a few images is still masked.', '<b>Les trous sont comblés.</b> Entre deux détections, la boîte est interpolée : un visage manqué pendant quelques images reste masqué.', '<b>Los huecos se rellenan.</b> Entre dos detecciones la caja se interpola, así que un rostro omitido durante unas imágenes sigue enmascarado.', '<b>تُملأ الفجوات.</b> بين عمليتي كشف يُستوفى المربع، فيبقى الوجه الذي فاتنا بضع صور مقنَّعًا.', '<b>Boşluklar doldurulur.</b> İki algılama arasında kutu enterpolasyonla hesaplanır; birkaç görüntü kaçan bir yüz yine de maskelenir.'],
  'h.s5f2': ['<b>Early and late.</b> Each mask starts 4 images before the first detection and ends 4 images after the last (about 0.13 s), because a face is often hard to see as it enters or leaves.', '<b>Tôt et tard.</b> Chaque masque commence 4 images avant la première détection et finit 4 images après la dernière (environ 0,13 s), car un visage est souvent difficile à voir quand il entre ou sort.', '<b>Antes y después.</b> Cada máscara empieza 4 imágenes antes de la primera detección y termina 4 después de la última (unos 0,13 s), porque un rostro suele ser difícil de ver al entrar o salir.', '<b>مبكرًا ومتأخرًا.</b> يبدأ كل قناع قبل أول كشف بـ4 صور وينتهي بعد آخر كشف بـ4 صور (نحو 0.13 ثانية)، لأن الوجه يصعب رؤيته غالبًا عند دخوله أو خروجه.', '<b>Erken ve geç.</b> Her maske ilk algılamadan 4 görüntü önce başlar ve sonuncudan 4 görüntü sonra biter (yaklaşık 0,13 sn); çünkü bir yüz girerken veya çıkarken çoğu zaman zor görülür.'],
  'h.s5f3': ['<b>Both directions.</b> Once a face is confirmed, the tracker also looks backward in time: weaker detections just before it, at the same place and size, are attached to the same face. A face turning towards the camera or walking into the frame is masked from its first faint trace, not only from the moment it became clear.', '<b>Dans les deux sens.</b> Une fois un visage confirmé, le suivi regarde aussi en arrière dans le temps : les détections plus faibles juste avant, au même endroit et à la même taille, sont rattachées au même visage. Un visage qui se tourne vers la caméra ou entre dans le cadre est masqué dès sa première trace ténue, pas seulement à partir du moment où il devient net.', '<b>En ambos sentidos.</b> Una vez confirmado un rostro, el seguimiento también mira hacia atrás en el tiempo: las detecciones más débiles justo antes, en el mismo lugar y tamaño, se asocian al mismo rostro. Un rostro que se vuelve hacia la cámara o entra en el encuadre se enmascara desde su primer indicio débil, no solo desde que se vuelve nítido.', '<b>في الاتجاهين.</b> بعد تأكيد الوجه ينظر المتتبّع أيضًا إلى الوراء في الزمن: تُربط عمليات الكشف الأضعف قبله مباشرة، في المكان والحجم نفسيهما، بالوجه نفسه. فالوجه الذي يلتفت نحو الكاميرا أو يدخل الكادر يُقنَّع منذ أول أثر خافت له، لا من لحظة وضوحه فقط.', '<b>İki yönde.</b> Bir yüz doğrulandıktan sonra takipçi zamanda geriye de bakar: hemen öncesindeki, aynı yerdeki ve aynı boyuttaki daha zayıf algılamalar aynı yüze bağlanır. Kameraya dönen veya kadraja giren bir yüz, yalnızca belirginleştiği andan değil, ilk silik izinden itibaren maskelenir.'],
  'h.s5f4': ['<b>Smoothing.</b> The position and size of each face are smoothed over about 2 images before and after (no delay, since the whole video is already analysed), and the box is widened just enough to still contain every detection. Masks do not shake.', '<b>Lissage.</b> La position et la taille de chaque visage sont lissées sur environ 2 images avant et après (sans délai, puisque toute la vidéo est déjà analysée), et la boîte est élargie juste assez pour contenir chaque détection. Les masques ne tremblent pas.', '<b>Suavizado.</b> La posición y el tamaño de cada rostro se suavizan sobre unas 2 imágenes antes y después (sin retraso, ya que todo el vídeo está analizado) y la caja se ensancha lo justo para seguir conteniendo cada detección. Las máscaras no tiemblan.', '<b>التنعيم.</b> يُنعَّم موضع كل وجه وحجمه على نحو صورتين قبل وبعد (دون تأخير لأن الفيديو كله محلَّل مسبقًا)، ويُوسَّع المربع بالقدر الكافي ليحتوي كل عملية كشف. فلا ترتجف الأقنعة.', '<b>Yumuşatma.</b> Her yüzün konumu ve boyutu öncesinde ve sonrasında yaklaşık 2 görüntü üzerinden yumuşatılır (video zaten tamamen analiz edildiği için gecikme olmaz) ve kutu, her algılamayı içerecek kadar genişletilir. Maskeler titremez.'],
  'h.s5f5': ['<b>Between images.</b> The mask is computed for the exact moment of each output image, between two analysed images, so a 60 images per second video gets 60 different masks, not 30 repeated ones.', '<b>Entre les images.</b> Le masque est calculé pour l’instant exact de chaque image de sortie, entre deux images analysées : une vidéo à 60 images par seconde reçoit 60 masques différents, pas 30 répétés.', '<b>Entre imágenes.</b> La máscara se calcula para el instante exacto de cada imagen de salida, entre dos imágenes analizadas, así que un vídeo de 60 imágenes por segundo recibe 60 máscaras distintas, no 30 repetidas.', '<b>بين الصور.</b> يُحسَب القناع للحظة الدقيقة لكل صورة في الناتج، بين صورتين محلَّلتين، فيحصل فيديو بمعدل 60 صورة في الثانية على 60 قناعًا مختلفًا لا 30 قناعًا مكررًا.', '<b>Görüntüler arası.</b> Maske, çıktının her görüntüsünün tam anı için iki analiz edilmiş görüntü arasında hesaplanır; saniyede 60 görüntülü bir video 30 tekrarlı değil 60 farklı maske alır.'],
  'h.s5f6': ['<b>Fast movement.</b> A face is looked for where its speed says it should be, not only where it was, so a quick pan does not cut one face into several.', '<b>Mouvement rapide.</b> Un visage est cherché là où sa vitesse dit qu’il devrait être, pas seulement là où il était : un panoramique rapide ne coupe pas un visage en plusieurs.', '<b>Movimiento rápido.</b> Un rostro se busca donde su velocidad indica que debería estar, no solo donde estaba, así que un barrido rápido no parte un rostro en varios.', '<b>الحركة السريعة.</b> يُبحَث عن الوجه حيث تقول سرعته إنه ينبغي أن يكون، لا حيث كان فقط، فلا يقسم التحريك السريع وجهًا واحدًا إلى عدة وجوه.', '<b>Hızlı hareket.</b> Bir yüz yalnızca bulunduğu yerde değil, hızının olması gerektiğini söylediği yerde aranır; hızlı bir kaydırma tek yüzü birkaça bölmez.'],
  'h.s5f7': ['<b>Best tracking (optional).</b> Slower: the weaker detections are checked again on a zoom, and every gap inside a face’s track is searched again, image by image, on a zoom around where the face should be.', '<b>Meilleur suivi (facultatif).</b> Plus lent : les détections plus faibles sont revérifiées sur un zoom, et chaque trou dans la trace d’un visage est recherché de nouveau, image par image, sur un zoom autour de l’endroit où le visage devrait être.', '<b>Mejor seguimiento (opcional).</b> Más lento: las detecciones más débiles se comprueban de nuevo con un zoom y cada hueco en la traza de un rostro se busca otra vez, imagen a imagen, con un zoom alrededor de donde debería estar el rostro.', '<b>أفضل تتبّع (اختياري).</b> أبطأ: تُفحص عمليات الكشف الأضعف مرة أخرى بتكبير، وتُعاد البحث عن كل فجوة داخل مسار الوجه، صورة بصورة، بتكبير حول المكان المتوقع للوجه.', '<b>En iyi takip (isteğe bağlı).</b> Daha yavaş: zayıf algılamalar yakınlaştırmayla yeniden denetlenir ve bir yüzün izindeki her boşluk, yüzün olması gereken yerin çevresinde yakınlaştırarak görüntü görüntü yeniden aranır.'],
  'h.s5f8': ['<b>Size.</b> The final box is larger than the face, plus a few pixels, so hair, chin and ears are covered. A slider in the review step sets it from 100% to 200% of the detected face (130% by default), and your edits are kept when you change it.', '<b>Taille.</b> La boîte finale est plus grande que le visage, plus quelques pixels, pour couvrir cheveux, menton et oreilles. Un curseur à l’étape de vérification la règle de 100 % à 200 % du visage détecté (130 % par défaut), et vos modifications sont conservées quand vous la changez.', '<b>Tamaño.</b> La caja final es mayor que el rostro, más unos píxeles, para cubrir pelo, barbilla y orejas. Un control deslizante en el paso de revisión la ajusta del 100 % al 200 % del rostro detectado (130 % por defecto) y tus ediciones se conservan al cambiarla.', '<b>الحجم.</b> المربع النهائي أكبر من الوجه بإضافة بضعة بكسلات ليغطي الشعر والذقن والأذنين. يضبطه شريط تمرير في خطوة المراجعة من 100٪ إلى 200٪ من الوجه المكتشف (130٪ افتراضيًا)، وتبقى تعديلاتك عند تغييره.', '<b>Boyut.</b> Son kutu, saçı, çeneyi ve kulakları kapsamak için yüzden birkaç piksel daha büyüktür. Gözden geçirme adımındaki bir kaydırıcı onu algılanan yüzün %100’ü ile %200’ü arasında ayarlar (varsayılan %130) ve değiştirdiğinizde düzenlemeleriniz korunur.'],

  'h.s6': ['6 · Your review', '6 · Votre vérification', '6 · Tu revisión', '6 · مراجعتك', '6 · Gözden geçirmeniz'],
  'h.s6p1': ['You see the result before anything is saved. Tap a mask to remove it (from that image on), or restore it. Tap anywhere else to add a mask by hand, drag it, resize it, or extend it to the whole video. Scrub the timeline or step image by image to check, and use Compare to slide between the masked and the original picture. If there is no mask at all, Anonyx says so and asks you to confirm before it exports.', 'Vous voyez le résultat avant que rien ne soit enregistré. Touchez un masque pour le retirer (à partir de cette image) ou le rétablir. Touchez ailleurs pour ajouter un masque à la main, le déplacer, le redimensionner ou l’étendre à toute la vidéo. Parcourez la ligne de temps ou avancez image par image pour vérifier, et utilisez Comparer pour glisser entre l’image masquée et l’originale. S’il n’y a aucun masque, Anonyx le dit et demande confirmation avant d’exporter.', 'Ves el resultado antes de guardar nada. Toca una máscara para quitarla (desde esa imagen) o restaurarla. Toca en cualquier otro sitio para añadir una máscara a mano, moverla, cambiarle el tamaño o extenderla a todo el vídeo. Recorre la línea de tiempo o avanza imagen a imagen para comprobar, y usa Comparar para deslizarte entre la imagen enmascarada y la original. Si no hay ninguna máscara, Anonyx lo dice y pide confirmación antes de exportar.', 'ترى النتيجة قبل حفظ أي شيء. المس قناعًا لإزالته (من تلك الصورة فصاعدًا) أو لاستعادته. المس أي مكان آخر لإضافة قناع يدويًا أو سحبه أو تغيير حجمه أو تمديده إلى الفيديو كله. تنقّل على الخط الزمني أو تقدّم صورة بصورة للتحقق، واستخدم «مقارنة» للتنقل بين الصورة المقنَّعة والأصلية. وإن لم يكن هناك أي قناع يخبرك Anonyx بذلك ويطلب التأكيد قبل التصدير.', 'Hiçbir şey kaydedilmeden önce sonucu görürsünüz. Bir maskeyi kaldırmak (o görüntüden itibaren) veya geri yüklemek için ona dokunun. Elle maske eklemek, sürüklemek, yeniden boyutlandırmak veya tüm videoya yaymak için başka bir yere dokunun. Kontrol etmek için zaman çizgisinde gezinin veya görüntü görüntü ilerleyin; maskeli ve orijinal görüntü arasında kaymak için Karşılaştır’ı kullanın. Hiç maske yoksa Anonyx bunu söyler ve dışa aktarmadan önce onay ister.'],
  'h.s6p2': ['<b>Keep only one face.</b> In an interview or a news report, one person may need to stay visible. Select that face and press ◉: it is unmasked and every other detected face is masked. If the same person was split into several tracks, repeat for each. Faces that were never detected stay visible, so check the whole video.', '<b>Garder un seul visage.</b> Dans une interview ou un reportage, une personne peut devoir rester visible. Sélectionnez ce visage et touchez ◉ : il est démasqué et tous les autres visages détectés sont masqués. Si la même personne a été scindée en plusieurs suivis, recommencez pour chacun. Les visages jamais détectés restent visibles : vérifiez donc toute la vidéo.', '<b>Dejar un solo rostro.</b> En una entrevista o un reportaje, puede que una persona deba quedar visible. Selecciona ese rostro y pulsa ◉: se desenmascara y todos los demás rostros detectados se enmascaran. Si la misma persona se dividió en varios seguimientos, repite para cada uno. Los rostros que nunca se detectaron siguen visibles, así que revisa todo el vídeo.', '<b>إبقاء وجه واحد فقط.</b> في مقابلة أو تقرير إخباري قد يلزم أن يبقى شخص واحد ظاهرًا. حدّد ذلك الوجه واضغط ◉: يُزال قناعه وتُقنَّع كل الوجوه الأخرى المكتشفة. إذا انقسم الشخص نفسه إلى عدة مسارات فكرّر ذلك لكل منها. الوجوه التي لم تُكتشف أصلًا تبقى ظاهرة، لذا راجع الفيديو كله.', '<b>Yalnızca bir yüzü açık bırakma.</b> Bir röportajda veya haberde bir kişinin görünür kalması gerekebilir. O yüzü seçip ◉ düğmesine basın: maskesi kalkar, algılanan diğer tüm yüzler maskelenir. Aynı kişi birkaç ize bölündüyse her biri için tekrarlayın. Hiç algılanmamış yüzler görünür kalır; bu yüzden videonun tamamını kontrol edin.'],
  'h.s6p3': ['The style is a solid black square, an emoji or, as an option, a blur. The blur shrinks the face area to a grid of cells (about 6 by 6 by default, from 3 by 3 to 11 by 11 with the strength slider) and scales it back up: detail is gone, but colours and rough shape remain, so it hides less than a solid square and is marked as such.', 'Le style est un carré noir plein, un émoji ou, en option, un flou. Le flou réduit la zone du visage à une grille de cellules (environ 6 par 6 par défaut, de 3 par 3 à 11 par 11 avec le curseur de force) puis la réagrandit : le détail disparaît, mais couleurs et forme approximative subsistent, il cache donc moins qu’un carré plein et il est signalé comme tel.', 'El estilo es un cuadrado negro sólido, un emoji o, como opción, un desenfoque. El desenfoque reduce la zona del rostro a una cuadrícula de celdas (unas 6 por 6 por defecto, de 3 por 3 a 11 por 11 con el control de intensidad) y la vuelve a ampliar: se pierde el detalle, pero quedan los colores y la forma aproximada, así que oculta menos que un cuadrado sólido y se indica como tal.', 'الشكل مربع أسود مصمت أو إيموجي أو تمويه كخيار. يقلّص التمويه منطقة الوجه إلى شبكة من الخلايا (نحو 6×6 افتراضيًا، من 3×3 إلى 11×11 بحسب شريط القوة) ثم يكبّرها: يضيع التفصيل لكن تبقى الألوان والشكل التقريبي، فهو يخفي أقل من المربع المصمت ويُنبَّه إلى ذلك.', 'Stil, düz siyah kare, emoji veya isteğe bağlı olarak bulanıklıktır. Bulanıklık yüz alanını bir hücre ızgarasına küçültür (varsayılan yaklaşık 6’ya 6; güç kaydırıcısıyla 3’e 3 ile 11’e 11 arası) ve yeniden büyütür: ayrıntı kaybolur ama renkler ve kabaca şekil kalır; bu yüzden düz kareden daha az gizler ve bu şekilde işaretlenir.'],
  'h.s6p4': ['The Report button lists how many faces were tracked, which ones to double-check (seen only briefly or with a low score, each with a button that jumps to it), how many masks you added or edited, and the share of frames that carry a mask. The same report is shown again at the end.', 'Le bouton Rapport indique combien de visages ont été suivis, lesquels revérifier (vus brièvement ou à score faible, chacun avec un bouton qui y mène), combien de masques vous avez ajoutés ou modifiés, et la part d’images qui portent un masque. Le même rapport est affiché de nouveau à la fin.', 'El botón Informe indica cuántos rostros se siguieron, cuáles revisar de nuevo (vistos solo brevemente o con puntuación baja, cada uno con un botón que lleva a él), cuántas máscaras añadiste o editaste y qué parte de las imágenes lleva máscara. El mismo informe se muestra de nuevo al final.', 'يعرض زر «تقرير» عدد الوجوه المتتبَّعة، وأيها يستحق إعادة التحقق (التي ظهرت لوقت قصير أو بدرجة منخفضة، ولكل منها زر ينقلك إليه)، وعدد الأقنعة التي أضفتها أو عدّلتها، ونسبة الإطارات التي تحمل قناعًا. ويظهر التقرير نفسه مرة أخرى في النهاية.', 'Rapor düğmesi kaç yüzün takip edildiğini, hangilerinin tekrar kontrol edilmesi gerektiğini (kısa görülenler veya düşük puanlılar; her birine götüren bir düğmeyle), kaç maske eklediğinizi veya düzenlediğinizi ve maske taşıyan karelerin oranını listeler. Aynı rapor sonda yeniden gösterilir.'],
  'h.s6p5': ['For an emoji, the black square is always painted first and the emoji on top, so the face can never show through the emoji’s rounded edges.', 'Pour un émoji, le carré noir est toujours peint d’abord et l’émoji par-dessus : le visage ne peut jamais apparaître par les bords arrondis de l’émoji.', 'Con un emoji, el cuadrado negro se pinta siempre primero y el emoji encima, de modo que el rostro nunca puede asomar por los bordes redondeados del emoji.', 'عند استخدام إيموجي يُرسَم المربع الأسود أولًا دائمًا ثم الإيموجي فوقه، فلا يمكن للوجه أن يظهر من الحواف المستديرة للإيموجي.', 'Emoji kullanıldığında önce her zaman siyah kare, üstüne emoji çizilir; böylece yüz emojinin yuvarlak kenarlarından asla görünmez.'],

  'h.s7': ['7 · Export', '7 · Export', '7 · Exportación', '7 · التصدير', '7 · Dışa aktarma'],
  'h.s7p': ['The saved file is built from scratch: every image is redrawn, the masks are painted on it, and the images are encoded again. The original file is never copied, so nothing in it can leak through.', 'Le fichier enregistré est reconstruit de zéro : chaque image est redessinée, les masques y sont peints et les images sont encodées de nouveau. Le fichier d’origine n’est jamais copié : rien de ce qu’il contient ne peut fuiter.', 'El archivo guardado se construye desde cero: cada imagen se redibuja, se le pintan las máscaras y las imágenes se codifican de nuevo. El archivo original nunca se copia, así que nada de lo que contiene puede filtrarse.', 'يُبنى الملف المحفوظ من الصفر: تُعاد رسم كل صورة وتُرسَم عليها الأقنعة ثم تُرمَّز الصور من جديد. لا يُنسَخ الملف الأصلي أبدًا، فلا يمكن لأي شيء فيه أن يتسرّب.', 'Kaydedilen dosya sıfırdan oluşturulur: her görüntü yeniden çizilir, maskeler üzerine boyanır ve görüntüler yeniden kodlanır. Özgün dosya asla kopyalanmaz; içindeki hiçbir şey sızamaz.'],
  'h.c3aria': ['Original image, painted mask, new encoded file', 'Image d’origine, masque peint, nouveau fichier encodé', 'Imagen original, máscara pintada, archivo nuevo codificado', 'الصورة الأصلية، القناع المرسوم، الملف الجديد المرمَّز', 'Özgün görüntü, çizilmiş maske, yeni kodlanmış dosya'],
  'h.c3a': ['original', 'original', 'original', 'الأصل', 'orijinal'],
  'h.c3b': ['masked', 'masqué', 'enmascarado', 'مقنَّع', 'maskeli'],
  'h.c3c': ['new file', 'nouveau fichier', 'archivo nuevo', 'ملف جديد', 'yeni dosya'],
  'h.s7f1': ['<b>Fast export.</b> Where the browser supports it (WebCodecs), each image is decoded, masked and encoded again, as H.264 in an MP4 file, or as VP9 in a WebM file on devices without an H.264 encoder. This runs faster than real time.', '<b>Export rapide.</b> Quand le navigateur le permet (WebCodecs), chaque image est décodée, masquée et encodée de nouveau, en H.264 dans un fichier MP4, ou en VP9 dans un fichier WebM sur les appareils sans encodeur H.264. Cela va plus vite que le temps réel.', '<b>Exportación rápida.</b> Cuando el navegador lo admite (WebCodecs), cada imagen se decodifica, se enmascara y se codifica de nuevo, como H.264 en un archivo MP4 o como VP9 en un archivo WebM en dispositivos sin codificador H.264. Va más rápido que el tiempo real.', '<b>التصدير السريع.</b> حيث يدعمه المتصفح (WebCodecs) تُفكّ ترميز كل صورة وتُقنَّع وتُرمَّز من جديد، بصيغة H.264 في ملف MP4، أو VP9 في ملف WebM على الأجهزة التي لا تملك مرمِّز H.264. يعمل أسرع من الزمن الفعلي.', '<b>Hızlı dışa aktarma.</b> Tarayıcı destekliyorsa (WebCodecs) her görüntü çözülür, maskelenir ve yeniden kodlanır: MP4 dosyasında H.264 olarak, H.264 kodlayıcısı olmayan cihazlarda WebM dosyasında VP9 olarak. Gerçek zamandan hızlı çalışır.'],
  'h.s7f2': ['<b>Size and limit.</b> By default the bitrate is between 2.5 and 10 Mbit/s depending on the size. You can cap the resolution (1080p, 720p, 480p) and choose a size limit: 16 MB (WhatsApp videos) or 100 MB (Signal). The tool then lowers the bitrate and, if needed, the resolution to fit, and shows the estimated size. A long video cannot fit in 16 MB without losing quality: the tool says so.', '<b>Taille et limite.</b> Par défaut, le débit est compris entre 2,5 et 10 Mbit/s selon la taille. Vous pouvez plafonner la résolution (1080p, 720p, 480p) et choisir une limite de poids : 16 Mo (vidéos WhatsApp) ou 100 Mo (Signal). L’outil baisse alors le débit et, si besoin, la résolution pour y tenir, et affiche le poids estimé. Une longue vidéo ne tient pas dans 16 Mo sans perdre en qualité : l’outil le signale.', '<b>Tamaño y límite.</b> Por defecto la tasa de bits está entre 2,5 y 10 Mbit/s según el tamaño. Puedes limitar la resolución (1080p, 720p, 480p) y elegir un límite de peso: 16 MB (vídeos de WhatsApp) o 100 MB (Signal). Entonces la herramienta reduce la tasa de bits y, si hace falta, la resolución para ajustarse, y muestra el peso estimado. Un vídeo largo no cabe en 16 MB sin perder calidad: la herramienta lo indica.', '<b>الحجم والحد.</b> افتراضيًا يتراوح معدل البت بين 2.5 و10 ميغابت/ث بحسب الأبعاد. يمكنك تحديد سقف للدقة (1080p أو 720p أو 480p) واختيار حد للحجم: 16 م.ب (فيديوهات واتساب) أو 100 م.ب (سيجنال). عندها تخفّض الأداة معدل البت وعند الحاجة الدقة لتناسب الحد، وتعرض الحجم المقدَّر. الفيديو الطويل لا يتسع في 16 م.ب دون خسارة الجودة، والأداة تنبّه إلى ذلك.', '<b>Boyut ve sınır.</b> Varsayılan olarak bit hızı boyuta göre 2,5 ile 10 Mbit/sn arasındadır. Çözünürlüğe üst sınır koyabilir (1080p, 720p, 480p) ve boyut sınırı seçebilirsiniz: 16 MB (WhatsApp videoları) veya 100 MB (Signal). Araç sığması için bit hızını ve gerekirse çözünürlüğü düşürür, tahmini boyutu gösterir. Uzun bir video kaliteden ödün vermeden 16 MB’a sığmaz; araç bunu belirtir.'],
  'h.s7f3': ['<b>Standard export.</b> Otherwise, the video is played in real time and the masked picture is recorded. The screen must stay on. The voice option is not available in this mode: the video is then silent.', '<b>Export standard.</b> Sinon, la vidéo est lue en temps réel et l’image masquée est enregistrée. L’écran doit rester allumé. L’option voix n’existe pas dans ce mode : la vidéo est alors muette.', '<b>Exportación estándar.</b> En caso contrario, el vídeo se reproduce en tiempo real y se graba la imagen enmascarada. La pantalla debe seguir encendida. La opción de voz no está disponible en este modo: el vídeo queda sin sonido.', '<b>التصدير العادي.</b> وإلا يُشغَّل الفيديو بالزمن الفعلي وتُسجَّل الصورة المقنَّعة. يجب أن تبقى الشاشة مضاءة. خيار الصوت غير متاح في هذا الوضع: يصبح الفيديو صامتًا.', '<b>Standart dışa aktarma.</b> Aksi hâlde video gerçek zamanlı oynatılır ve maskeli görüntü kaydedilir. Ekran açık kalmalıdır. Ses seçeneği bu modda yoktur: video sessiz olur.'],
  'h.s7f4': ['<b>Sound.</b> Off by default, since a voice can identify someone. Three choices: <b>mute</b> (no audio at all), <b>voice</b> (pitch and tone shifted down by about 20%, which makes recognition harder but not impossible, and the words stay audible) and <b>sound</b> (original audio kept).', '<b>Son.</b> Coupé par défaut, car une voix peut identifier quelqu’un. Trois choix : <b>muet</b> (aucun audio), <b>voix</b> (hauteur et timbre abaissés d’environ 20 %, ce qui rend la reconnaissance plus difficile sans l’empêcher, et les mots restent audibles) et <b>son</b> (audio d’origine conservé).', '<b>Sonido.</b> Desactivado por defecto, porque una voz puede identificar a alguien. Tres opciones: <b>sin sonido</b> (ningún audio), <b>voz</b> (tono y timbre bajados un 20 % aproximadamente, lo que dificulta el reconocimiento sin impedirlo, y las palabras siguen siendo audibles) y <b>sonido</b> (se conserva el audio original).', '<b>الصوت.</b> معطَّل افتراضيًا لأن الصوت قد يكشف هوية صاحبه. ثلاثة خيارات: <b>صامت</b> (بلا أي صوت)، و<b>الصوت</b> (تُخفَّض النبرة والطابع بنحو 20٪، ما يصعّب التعرّف دون أن يمنعه وتبقى الكلمات مسموعة)، و<b>الأصلي</b> (يُحتفَظ بالصوت الأصلي).', '<b>Ses.</b> Bir ses kişiyi belli edebileceği için varsayılan olarak kapalıdır. Üç seçenek: <b>sessiz</b> (hiç ses yok), <b>ses</b> (perde ve tını yaklaşık %20 alçaltılır; bu, tanınmayı zorlaştırır ama imkânsız kılmaz, sözcükler anlaşılır kalır) ve <b>orijinal</b> (özgün ses korunur).'],
  'h.s7f5': ['<b>Metadata.</b> Location, phone model and original dates are not copied. In the MP4 header, creation dates and handler names are also zeroed.', '<b>Métadonnées.</b> Lieu, modèle de téléphone et dates d’origine ne sont pas copiés. Dans l’en-tête MP4, les dates de création et les noms de gestionnaire sont aussi remis à zéro.', '<b>Metadatos.</b> La ubicación, el modelo de teléfono y las fechas originales no se copian. En la cabecera MP4 también se ponen a cero las fechas de creación y los nombres de manejador.', '<b>البيانات الوصفية.</b> لا يُنسَخ الموقع ولا طراز الهاتف ولا التواريخ الأصلية. وفي ترويسة MP4 تُصفَّر أيضًا تواريخ الإنشاء وأسماء المعالجات.', '<b>Üstveri.</b> Konum, telefon modeli ve özgün tarihler kopyalanmaz. MP4 başlığında oluşturma tarihleri ve işleyici adları da sıfırlanır.'],
  'h.s7f6': ['<b>Photos.</b> Redrawn and saved as JPEG at 92% quality, or as PNG if you choose it. Orientation is applied and EXIF data (location, camera) is dropped.', '<b>Photos.</b> Redessinées et enregistrées en JPEG à 92 % de qualité, ou en PNG si vous le choisissez. L’orientation est appliquée et les données EXIF (lieu, appareil) sont supprimées.', '<b>Fotos.</b> Se redibujan y se guardan como JPEG con calidad del 92 %, o como PNG si lo eliges. Se aplica la orientación y se eliminan los datos EXIF (ubicación, cámara).', '<b>الصور.</b> يُعاد رسمها وتُحفَظ بصيغة JPEG بجودة 92٪، أو PNG إذا اخترتَ ذلك. تُطبَّق الاتجاهية وتُحذَف بيانات EXIF (الموقع والكاميرا).', '<b>Fotoğraflar.</b> Yeniden çizilir ve %92 kalitede JPEG olarak, isterseniz PNG olarak kaydedilir. Yönlendirme uygulanır ve EXIF verileri (konum, kamera) atılır.'],

  'h.s8': ['8 · What is kept', '8 · Ce qui est conservé', '8 · Qué se conserva', '8 · ما الذي يُحتفَظ به', '8 · Neler saklanır'],
  'h.s8p': ['Nothing. No cookie, no <code>localStorage</code>, no <code>sessionStorage</code>, no IndexedDB, no service worker, no analytics. Working data lives in memory and disappears when you close the tab or choose another file. The only thing that remains is the file you save yourself. Even the language is not stored: it is read from your browser each time, or from the address.', 'Rien. Aucun cookie, aucun <code>localStorage</code>, aucun <code>sessionStorage</code>, aucune IndexedDB, aucun service worker, aucune statistique. Les données de travail vivent en mémoire et disparaissent quand vous fermez l’onglet ou choisissez un autre fichier. Seul reste le fichier que vous enregistrez vous-même. Même la langue n’est pas mémorisée : elle est lue dans votre navigateur à chaque fois, ou dans l’adresse.', 'Nada. Ninguna cookie, ningún <code>localStorage</code>, ningún <code>sessionStorage</code>, ninguna IndexedDB, ningún service worker, ninguna analítica. Los datos de trabajo viven en memoria y desaparecen al cerrar la pestaña o elegir otro archivo. Lo único que queda es el archivo que guardas tú. Ni siquiera el idioma se guarda: se lee del navegador cada vez, o de la dirección.', 'لا شيء. لا ملفات تعريف ارتباط ولا <code>localStorage</code> ولا <code>sessionStorage</code> ولا IndexedDB ولا service worker ولا تحليلات. تعيش بيانات العمل في الذاكرة وتختفي عند إغلاق اللسان أو اختيار ملف آخر. الشيء الوحيد الذي يبقى هو الملف الذي تحفظه بنفسك. حتى اللغة لا تُخزَّن: تُقرأ من متصفحك في كل مرة أو من العنوان.', 'Hiçbir şey. Çerez yok, <code>localStorage</code> yok, <code>sessionStorage</code> yok, IndexedDB yok, service worker yok, analiz yok. Çalışma verileri bellekte durur ve sekmeyi kapattığınızda veya başka bir dosya seçtiğinizde kaybolur. Geriye yalnızca sizin kaydettiğiniz dosya kalır. Dil bile saklanmaz: her seferinde tarayıcınızdan veya adresten okunur.'],

  'h.s9': ['Limits, honestly', 'Les limites, honnêtement', 'Límites, con honestidad', 'الحدود، بصراحة', 'Sınırlar, dürüstçe'],
  'h.s9p1': ['A detector can miss faces: profiles, faces partly hidden by a hand or a hat, very small or very blurry faces, faces at the edge of the image. That is why the review step exists. Watch the whole result before posting.', 'Un détecteur peut manquer des visages : profils, visages à moitié cachés par une main ou un chapeau, visages très petits ou très flous, visages au bord de l’image. C’est pourquoi l’étape de vérification existe. Regardez tout le résultat avant de publier.', 'Un detector puede omitir rostros: perfiles, rostros parcialmente ocultos por una mano o un sombrero, rostros muy pequeños o muy borrosos, rostros en el borde de la imagen. Por eso existe el paso de revisión. Mira todo el resultado antes de publicar.', 'قد يفوت الكاشف وجوهًا: الوجوه الجانبية، والمخفية جزئيًا بيد أو قبعة، والصغيرة جدًا أو الضبابية جدًا، والتي عند حافة الصورة. لهذا توجد خطوة المراجعة. شاهد النتيجة كلها قبل النشر.', 'Bir algılayıcı yüzleri kaçırabilir: profiller, el veya şapkayla kısmen gizlenmiş yüzler, çok küçük veya çok bulanık yüzler, görüntü kenarındaki yüzler. Gözden geçirme adımı bu yüzden vardır. Paylaşmadan önce sonucun tamamını izleyin.'],
  'h.s9p2': ['A mask hides a face, not clothes, tattoos, a distinctive voice (unless you change it, and even then not for sure), a place or a name said aloud.', 'Un masque cache un visage, pas les vêtements, les tatouages, une voix reconnaissable (sauf si vous la changez, et même alors sans certitude), un lieu ou un nom prononcé à voix haute.', 'Una máscara oculta un rostro, no la ropa, los tatuajes, una voz distintiva (salvo que la cambies, y ni así con certeza), un lugar o un nombre dicho en voz alta.', 'القناع يخفي الوجه، لا الملابس ولا الوشوم ولا الصوت المميّز (إلا إذا غيّرته، وحتى حينها دون يقين) ولا المكان ولا اسمًا يُنطَق بصوت مسموع.', 'Maske bir yüzü gizler; kıyafetleri, dövmeleri, ayırt edici bir sesi (değiştirmediyseniz; değiştirseniz bile kesin olmaz), bir yeri veya yüksek sesle söylenen bir adı değil.'],

  'h.s10': ['Where to read it', 'Où le lire', 'Dónde leerlo', 'أين تقرأ الشيفرة', 'Nereden okunur'],
  'h.r1': ['<code>app.js</code> · screens, analysis loop, tracking, review, export.', '<code>app.js</code> · écrans, boucle d’analyse, suivi, vérification, export.', '<code>app.js</code> · pantallas, bucle de análisis, seguimiento, revisión, exportación.', '<code>app.js</code> · الشاشات وحلقة التحليل والتتبّع والمراجعة والتصدير.', '<code>app.js</code> · ekranlar, analiz döngüsü, takip, gözden geçirme, dışa aktarma.'],
  'h.r2': ['<code>detector.js</code> · model call, night pass, head pass, overlap merging, score rule.', '<code>detector.js</code> · appel du modèle, passe de nuit, passe têtes, fusion des chevauchements, règle de score.', '<code>detector.js</code> · llamada al modelo, pasada nocturna, pasada de cabezas, fusión de solapes, regla de puntuación.', '<code>detector.js</code> · استدعاء النموذج، مرحلة الليل، مرحلة الرؤوس، دمج التداخلات، قاعدة الدرجات.', '<code>detector.js</code> · model çağrısı, gece geçişi, baş geçişi, çakışma birleştirme, puan kuralı.'],
  'h.r3': ['<code>detect-worker.js</code> · runs the detector in the background. <code>voice.js</code> · the voice change.', '<code>detect-worker.js</code> · exécute le détecteur en arrière-plan. <code>voice.js</code> · le changement de voix.', '<code>detect-worker.js</code> · ejecuta el detector en segundo plano. <code>voice.js</code> · el cambio de voz.', '<code>detect-worker.js</code> · يشغّل الكاشف في الخلفية. <code>voice.js</code> · تغيير الصوت.', '<code>detect-worker.js</code> · algılayıcıyı arka planda çalıştırır. <code>voice.js</code> · ses değiştirme.'],
  'h.r4': ['<code>vendor/</code> · ONNX Runtime and Mediabunny, unmodified. <code>models/</code> · the YuNet model.', '<code>vendor/</code> · ONNX Runtime et Mediabunny, non modifiés. <code>models/</code> · le modèle YuNet.', '<code>vendor/</code> · ONNX Runtime y Mediabunny, sin modificar. <code>models/</code> · el modelo YuNet.', '<code>vendor/</code> · ONNX Runtime وMediabunny دون تعديل. <code>models/</code> · نموذج YuNet.', '<code>vendor/</code> · ONNX Runtime ve Mediabunny, değiştirilmemiş. <code>models/</code> · YuNet modeli.'],
  'h.end': ['Everything is on <a href="' + REPO + '">github.com/yakuzaax/anonyx</a>. To check the privacy claims yourself, see <a href="verify.html">Verify Anonyx</a>.', 'Tout est sur <a href="' + REPO + '">github.com/yakuzaax/anonyx</a>. Pour vérifier vous-même les promesses de confidentialité, voir <a href="verify.html">Vérifier Anonyx</a>.', 'Todo está en <a href="' + REPO + '">github.com/yakuzaax/anonyx</a>. Para comprobar tú mismo las promesas de privacidad, consulta <a href="verify.html">Verificar Anonyx</a>.', 'كل شيء على <a href="' + REPO + '">github.com/yakuzaax/anonyx</a>. وللتحقق بنفسك من وعود الخصوصية انظر <a href="verify.html">تحقّق من Anonyx</a>.', 'Her şey <a href="' + REPO + '">github.com/yakuzaax/anonyx</a> adresinde. Gizlilik taahhütlerini kendiniz doğrulamak için <a href="verify.html">Anonyx’ı doğrulayın</a> sayfasına bakın.'],
});
